import math

def moe_sample_sizes(sizes, rates, moe, z):
    result = []
    for size, rate in zip(sizes, rates):
        base = z * z * rate * (1 - rate) / (moe * moe)  # 不考虑总体规模时的样本量
        if base < 1:
            result.append(0)
        else:
            result.append(math.ceil(base / (1 + (base - 1) / size)))  # 有限总体校正
    return [result, sum(result)]

